  /** Speaker id (e.g. 'S1') to display name and colour. Words point here through word.speaker. */
  speakers?: {
    [k: string]: Speaker;
  };
  /** Explicit cut ranges. Cuts from deleted words are derived from words and are not listed here. */
  cuts: Cut[];
  /** Clip in/out: everything outside is excluded from export. */
  range?: Range | null;
  zooms: Zoom[];
