  style: Style;
  /** Surfaces: macos, tauri. */
  cursor?: Cursor;
  captions: Captions;
  audio?: Audio;
  /** Brand kit applied to this project (ticket S-02). */
  brand?: Brand;
  /** B-roll images and clips over the screen area or the whole frame (ticket S-04), local or generated with the user's own cloud key. */
  broll?: BrollOverlay[];
  /** Background music bed (ticket S-04). Unlike most fields it lives on the OUTPUT timeline (after cuts), so cuts never chop the song: it starts at `start`, loops if shorter than the video, fades in and out, and ducks under speech (kept words merged across gaps under 0.5 s; smoothstep attack/release). Gain at output time t = volume × fade × (1 − duck × (1 − duckLevel)); see packages/editor-core/src/music.js. */
